package com.meddibuddy.config;
import com.meddibuddy.user.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.core.env.Environment;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DemoAdminSeed { @Bean CommandLineRunner seedAdmin(AppUserRepository users,PasswordEncoder encoder,Environment env){return args->{String email=env.getProperty("APP_ADMIN_EMAIL"),password=env.getProperty("APP_ADMIN_PASSWORD");if(email!=null&&!email.isBlank()&&password!=null&&password.length()>=12&&!users.existsByEmailIgnoreCase(email))users.save(new AppUser("Administrator",email,encoder.encode(password),Role.ADMIN));};} }
